    'Виклади все в тарілку: білок, гарнір і овочі поруч': 'Put everything on a plate: protein, side and vegetables next to each other',
    'Запечи {x} в духовці при 200 °C 20–25 хв (або обсмаж на сковороді по 6–7 хв з кожного боку) — сік має бути прозорим': 'Bake {x} in the oven at 200 °C for 20–25 min (or pan-fry 6–7 min per side) — the juices should run clear',
    'Опусти {x} в киплячу воду на 9 хв, потім на 2 хв у холодну — легше почистити': 'Put {x} in boiling water for 9 min, then in cold water for 2 min — easier to peel',
    'Виклади {x} в тарілку — готувати не треба': 'Put {x} on the plate — no cooking needed',
    'Відкрий {x}, злий рідину й розбери виделкою': 'Open {x}, drain the liquid and flake with a fork',
    'Запечи {x} в духовці при 200 °C 12–15 хв шкірою донизу': 'Bake {x} in the oven at 200 °C for 12–15 min, skin side down',
