    'Наріж {x} шматочками, обсмаж 5 хв і тушкуй під кришкою 40–45 хв, підливаючи воду': 'Cut {x} into pieces, fry for 5 min and simmer covered for 40–45 min, adding water as needed',
    'Наріж {x} і обсмаж на сковороді 15–20 хв до золотистої скоринки': 'Slice {x} and pan-fry for 15–20 min until golden brown',
    'Обсмаж {x} на сковороді 10–12 хв, розбиваючи грудочки': 'Fry {x} in a pan for 10–12 min, breaking up the lumps',
    'Консервовану {x} промий і прогрій 3–5 хв (суху — замочи на ніч і вари 60–90 хв)': 'Rinse canned {x} and heat for 3–5 min (dried: soak overnight and boil for 60–90 min)',
    'Консервований {x} промий і прогрій 3–5 хв (сухий — замочи на ніч і вари 60–90 хв)': 'Rinse canned {x} and heat for 3–5 min (dried: soak overnight and boil for 60–90 min)',
    'Промий {x}, залий водою 1:2, доведи до кипіння й вари під кришкою на слабкому вогні 15–18 хв': 'Rinse {x}, cover with water 1:2, bring to a boil and cook covered on low heat for 15–18 min',
    'Промий {x}, залий водою 1:2 і вари під кришкою на слабкому вогні 15–20 хв': 'Rinse {x}, cover with water 1:2 and cook covered on low heat for 15–20 min',
    'Вари {x} в киплячій підсоленій воді 8–10 хв (як на пачці) і злий воду': 'Boil {x} in boiling salted water for 8–10 min (as on the package) and drain',
    'Почисть {x}, наріж частками й запечи при 200 °C 30–35 хв (або звари в підсоленій воді 20 хв)': 'Peel {x}, cut into wedges and bake at 200 °C for 30–35 min (or boil in salted water for 20 min)',
    'Залий {x} водою 1:2 і вари під кришкою 12–15 хв': 'Cover {x} with water 1:2 and cook covered for 12–15 min',
    'Залий {x} окропом 1:1, накрий на 5 хв і розпуши виделкою': 'Pour boiling water over {x} 1:1, cover for 5 min and fluff with a fork',
    'Промий {x}, залий водою 1:3 і вари 25–40 хв до м\'якості': 'Rinse {x}, cover with water 1:3 and cook for 25–40 min until tender',
    'Наріж {x} скибками; можна підсушити в тостері 2–3 хв': 'Cut {x} into slices; you can toast it in a toaster for 2–3 min',
    'Тонко нашаткуй {x} і пом\'ни руками з дрібкою солі — стане соковитішою': 'Shred {x} thinly and knead by hand with a pinch of salt — it becomes juicier',
