    'Gym Log не лікар і не підказує, що, скільки й як приймати. Це лише твій нагадувач: дозування, курс і уколи — тільки за призначенням лікаря.': 'Gym Log nie jest lekarzem i nie podpowiada, co, ile i jak przyjmować. To tylko twoje przypomnienie: dawkowanie, kuracja i zastrzyki — wyłącznie zgodnie z zaleceniem lekarza.',
