    'Запечи {x} в духовці при 200 °C 20–25 хв (або обсмаж на сковороді по 6–7 хв з кожного боку) — сік має бути прозорим': 'Upiecz {x} w piekarniku w 200 °C przez 20–25 min (albo smaż na patelni po 6–7 min z każdej strony) — sok ma być przezroczysty',
    'Опусти {x} в киплячу воду на 9 хв, потім на 2 хв у холодну — легше почистити': 'Włóż {x} do wrzącej wody na 9 min, potem na 2 min do zimnej — łatwiej obrać',
