    'Запечи {x} в духовці при 200 °C 15–20 хв (або обсмаж по 4 хв з кожного боку)': 'Upiecz {x} w piekarniku w 200 °C przez 15–20 min (albo smaż po 4 min z każdej strony)',
    'Наріж {x} шматочками, обсмаж 5 хв і тушкуй під кришкою 40–45 хв, підливаючи воду': 'Pokrój {x} w kawałki, smaż 5 min i duś pod przykryciem 40–45 min, podlewając wodą',
    'Наріж {x} і обсмаж на сковороді 15–20 хв до золотистої скоринки': 'Pokrój {x} i smaż na patelni 15–20 min do złotej skórki',
    'Обсмаж {x} на сковороді 10–12 хв, розбиваючи грудочки': 'Smaż {x} na patelni 10–12 min, rozgniatając grudki',
