    'Промий {x}, залий водою 1:2 і вари під кришкою на слабкому вогні 15–20 хв': 'Przepłucz {x}, zalej wodą 1:2 i gotuj pod przykryciem na małym ogniu 15–20 min',
    'Вари {x} в киплячій підсоленій воді 8–10 хв (як на пачці) і злий воду': 'Gotuj {x} we wrzącej osolonej wodzie 8–10 min (jak na opakowaniu) i odcedź',
    'Почисть {x}, наріж частками й запечи при 200 °C 30–35 хв (або звари в підсоленій воді 20 хв)': 'Obierz {x}, pokrój w cząstki i piecz w 200 °C 30–35 min (albo gotuj w osolonej wodzie 20 min)',
