    'Виклади все в тарілку: білок, гарнір і овочі поруч': 'Alles auf dem Teller anrichten: Eiweiß, Beilage und Gemüse nebeneinander',
    'Запечи {x} в духовці при 200 °C 20–25 хв (або обсмаж на сковороді по 6–7 хв з кожного боку) — сік має бути прозорим': '{x} im Ofen bei 200 °C 20–25 Min. backen (oder in der Pfanne je 6–7 Min. pro Seite braten) — der Saft sollte klar sein',
    'Опусти {x} в киплячу воду на 9 хв, потім на 2 хв у холодну — легше почистити': '{x} 9 Min. in kochendes Wasser geben, dann 2 Min. in kaltes — so lässt es sich leichter schälen',
    'Виклади {x} в тарілку — готувати не треба': '{x} auf den Teller legen — Kochen ist nicht nötig',
    'Відкрий {x}, злий рідину й розбери виделкою': '{x} öffnen, die Flüssigkeit abgießen und mit einer Gabel zerpflücken',
    'Запечи {x} в духовці при 200 °C 12–15 хв шкірою донизу': '{x} im Ofen bei 200 °C 12–15 Min. mit der Hautseite nach unten backen',
    'Запечи {x} в духовці при 200 °C 15–20 хв (або обсмаж по 4 хв з кожного боку)': '{x} im Ofen bei 200 °C 15–20 Min. backen (oder je 4 Min. pro Seite braten)',
    'Наріж {x} шматочками, обсмаж 5 хв і тушкуй під кришкою 40–45 хв, підливаючи воду': '{x} in Stücke schneiden, 5 Min. anbraten und zugedeckt 40–45 Min. schmoren, bei Bedarf Wasser nachgießen',
    'Наріж {x} і обсмаж на сковороді 15–20 хв до золотистої скоринки': '{x} schneiden und 15–20 Min. in der Pfanne goldbraun braten',
    'Обсмаж {x} на сковороді 10–12 хв, розбиваючи грудочки': '{x} 10–12 Min. in der Pfanne braten und dabei die Klümpchen zerdrücken',
    'Консервовану {x} промий і прогрій 3–5 хв (суху — замочи на ніч і вари 60–90 хв)': '{x} aus der Dose abspülen und 3–5 Min. erwärmen (getrocknet: über Nacht einweichen und 60–90 Min. kochen)',
    'Консервований {x} промий і прогрій 3–5 хв (сухий — замочи на ніч і вари 60–90 хв)': '{x} aus der Dose abspülen und 3–5 Min. erwärmen (getrocknet: über Nacht einweichen und 60–90 Min. kochen)',
    'Промий {x}, залий водою 1:2, доведи до кипіння й вари під кришкою на слабкому вогні 15–18 хв': '{x} abspülen, im Verhältnis 1:2 mit Wasser aufgießen, aufkochen und zugedeckt bei schwacher Hitze 15–18 Min. kochen',
    'Промий {x}, залий водою 1:2 і вари під кришкою на слабкому вогні 15–20 хв': '{x} abspülen, im Verhältnis 1:2 mit Wasser aufgießen und zugedeckt bei schwacher Hitze 15–20 Min. kochen',
    'Вари {x} в киплячій підсоленій воді 8–10 хв (як на пачці) і злий воду': '{x} 8–10 Min. in kochendem Salzwasser garen (wie auf der Packung) und abgießen',
    'Почисть {x}, наріж частками й запечи при 200 °C 30–35 хв (або звари в підсоленій воді 20 хв)': '{x} schälen, in Spalten schneiden und bei 200 °C 30–35 Min. backen (oder 20 Min. in Salzwasser kochen)',
    'Залий {x} водою 1:2 і вари під кришкою 12–15 хв': '{x} im Verhältnis 1:2 mit Wasser aufgießen und zugedeckt 12–15 Min. kochen',
    'Залий {x} окропом 1:1, накрий на 5 хв і розпуши виделкою': '{x} im Verhältnis 1:1 mit kochendem Wasser übergießen, 5 Min. zugedeckt quellen lassen und mit einer Gabel auflockern',
    'Промий {x}, залий водою 1:3 і вари 25–40 хв до м\'якості': '{x} abspülen, im Verhältnis 1:3 mit Wasser aufgießen und 25–40 Min. weich kochen',
