    'Записуй лише те, що призначив лікар. Gym Log не перевіряє дози й сумісність препаратів.': 'Anota solo lo que te ha recetado el médico. Gym Log no comprueba las dosis ni la compatibilidad de los medicamentos.',
    'Впиши назву': 'Escribe un nombre',
    'Видалити «{x}» разом з відмітками прийому?': '¿Eliminar «{x}» junto con las marcas de toma?',
    'Овочі посоли, поперчи й полий ложкою олії': 'Sala y pimienta las verduras y rocíalas con una cucharada de aceite',
    'Виклади все в тарілку: білок, гарнір і овочі поруч': 'Pon todo en el plato: proteína, guarnición y verduras juntas',
    'Запечи {x} в духовці при 200 °C 20–25 хв (або обсмаж на сковороді по 6–7 хв з кожного боку) — сік має бути прозорим': 'Hornea {x} a 200 °C durante 20–25 min (o fríe en sartén 6–7 min por cada lado) — el jugo debe salir transparente',
    'Опусти {x} в киплячу воду на 9 хв, потім на 2 хв у холодну — легше почистити': 'Sumerge {x} en agua hirviendo 9 min y luego 2 min en agua fría — se pela más fácil',
    'Виклади {x} в тарілку — готувати не треба': 'Pon {x} en el plato — no hace falta cocinar',
    'Відкрий {x}, злий рідину й розбери виделкою': 'Abre {x}, escurre el líquido y desmenuza con un tenedor',
    'Запечи {x} в духовці при 200 °C 12–15 хв шкірою донизу': 'Hornea {x} a 200 °C durante 12–15 min con la piel hacia abajo',
    'Запечи {x} в духовці при 200 °C 15–20 хв (або обсмаж по 4 хв з кожного боку)': 'Hornea {x} a 200 °C durante 15–20 min (o fríe 4 min por cada lado)',
    'Наріж {x} шматочками, обсмаж 5 хв і тушкуй під кришкою 40–45 хв, підливаючи воду': 'Corta {x} en trozos, sofríe 5 min y estofa tapado 40–45 min, añadiendo agua según haga falta',
    'Наріж {x} і обсмаж на сковороді 15–20 хв до золотистої скоринки': 'Corta {x} en láminas y fríe en sartén 15–20 min hasta que se dore',
    'Обсмаж {x} на сковороді 10–12 хв, розбиваючи грудочки': 'Fríe {x} en sartén 10–12 min, deshaciendo los grumos',
    'Консервовану {x} промий і прогрій 3–5 хв (суху — замочи на ніч і вари 60–90 хв)': '{x} de lata: enjuaga y calienta 3–5 min (seco: déjalo en remojo toda la noche y cuece 60–90 min)',
    'Консервований {x} промий і прогрій 3–5 хв (сухий — замочи на ніч і вари 60–90 хв)': '{x} de lata: enjuaga y calienta 3–5 min (seco: déjalo en remojo toda la noche y cuece 60–90 min)',
    'Промий {x}, залий водою 1:2, доведи до кипіння й вари під кришкою на слабкому вогні 15–18 хв': 'Enjuaga {x}, cubre con agua en proporción 1:2, lleva a ebullición y cuece tapado a fuego lento 15–18 min',
    'Промий {x}, залий водою 1:2 і вари під кришкою на слабкому вогні 15–20 хв': 'Enjuaga {x}, cubre con agua en proporción 1:2 y cuece tapado a fuego lento 15–20 min',
    'Вари {x} в киплячій підсоленій воді 8–10 хв (як на пачці) і злий воду': 'Hierve {x} en agua con sal hirviendo 8–10 min (como indica el envase) y escurre',
    'Почисть {x}, наріж частками й запечи при 200 °C 30–35 хв (або звари в підсоленій воді 20 хв)': 'Pela {x}, corta en gajos y hornea a 200 °C 30–35 min (o hierve en agua con sal 20 min)',
    'Залий {x} водою 1:2 і вари під кришкою 12–15 хв': 'Cubre {x} con agua en proporción 1:2 y cuece tapado 12–15 min',
    'Залий {x} окропом 1:1, накрий на 5 хв і розпуши виделкою': 'Cubre {x} con agua hirviendo en proporción 1:1, tapa 5 min y suelta con un tenedor',
    'Промий {x}, залий водою 1:3 і вари 25–40 хв до м\'якості': 'Enjuaga {x}, cubre con agua en proporción 1:3 y cuece 25–40 min hasta que esté tierno',
    'Наріж {x} скибками; можна підсушити в тостері 2–3 хв': 'Corta {x} en rebanadas; puedes tostar en la tostadora 2–3 min',
    'Тонко нашаткуй {x} і пом\'ни руками з дрібкою солі — стане соковитішою': 'Corta {x} en juliana fina y amasa con las manos con una pizca de sal — ganará jugosidad',
    'Натри {x} на тертці': 'Ralla {x}',
    'Розбери {x} на суцвіття й звари на парі 5–7 хв (або 4 хв у киплячій воді)': 'Separa {x} en ramilletes y cuece al vapor 5–7 min (o 4 min en agua hirviendo)',
    'Наріж {x} смужками': 'Corta {x} en tiras',
    'Наріж {x} кружальцями й обсмаж по 3–4 хв з кожного боку': 'Corta {x} en rodajas y fríe 3–4 min por cada lado',
    'Промий {x}; можна прогріти на сковороді 1–2 хв, щоб зів\'яв': 'Enjuaga {x}; puedes calentar en sartén 1–2 min para que se ablande',
    'Промий {x} і порви руками': 'Enjuaga {x} y rompe con las manos',
