    'Ірина': 'Iryna',
    "Їжа на 3 дні за годину: крупа, запечене м’ясо, овочі. Рецепти з калоріями — у розділі «Рецепти».": 'Comida para 3 días en una hora: cereales, carne al horno, verduras. Recetas con calorías en la sección «Recetas».',
    'Андрій': 'Andrii',
    'Атлет': 'Atleta',
    'Вода: 30–35 мл на кг ваги, у дні тренувань більше. Спрага — вже запізнення.': 'Agua: 30–35 ml por kg de peso, más en días de entrenamiento. La sed ya es tarde.',
    'Відкрити рецепти': 'Abrir recetas',
    'Відпочинок між підходами: 1–2 хв на легкі вправи, 2–4 хв на важкі базові. Таймер у застосунку підкаже сам.': 'Descanso entre series: 1–2 min en ejercicios ligeros, 2–4 min en los básicos pesados. El temporizador de la app te lo indica.',
