    'Gym Log не лікар і не підказує, що, скільки й як приймати. Це лише твій нагадувач: дозування, курс і уколи — тільки за призначенням лікаря.': 'Gym Log n\'est pas un médecin et ne dit pas quoi prendre, en quelle quantité ni comment. C\'est seulement ton rappel : dosage, cure et injections — uniquement sur prescription de ton médecin.',
