    'Записуй лише те, що призначив лікар. Gym Log не перевіряє дози й сумісність препаратів.': 'Note uniquement ce que ton médecin a prescrit. Gym Log ne vérifie ni les doses ni la compatibilité des médicaments.',
    'Впиши назву': 'Saisis un nom',
    'Видалити «{x}» разом з відмітками прийому?': 'Supprimer « {x} » avec les marques de prise ?',
    'Овочі посоли, поперчи й полий ложкою олії': 'Sale et poivre les légumes et arrose-les d\'une cuillère d\'huile',
    'Виклади все в тарілку: білок, гарнір і овочі поруч': 'Mets tout dans l\'assiette : protéine, accompagnement et légumes côte à côte',
    'Запечи {x} в духовці при 200 °C 20–25 хв (або обсмаж на сковороді по 6–7 хв з кожного боку) — сік має бути прозорим': 'Fais cuire {x} au four à 200 °C pendant 20–25 min (ou à la poêle 6–7 min de chaque côté) — le jus doit être clair',
    'Опусти {x} в киплячу воду на 9 хв, потім на 2 хв у холодну — легше почистити': 'Plonge {x} dans l\'eau bouillante 9 min, puis 2 min dans l\'eau froide — plus facile à éplucher',
    'Виклади {x} в тарілку — готувати не треба': 'Mets {x} dans l\'assiette — pas besoin de cuisson',
    'Відкрий {x}, злий рідину й розбери виделкою': 'Ouvre {x}, égoutte le liquide et effiloche à la fourchette',
    'Запечи {x} в духовці при 200 °C 12–15 хв шкірою донизу': 'Fais cuire {x} au four à 200 °C pendant 12–15 min, côté peau en dessous',
    'Запечи {x} в духовці при 200 °C 15–20 хв (або обсмаж по 4 хв з кожного боку)': 'Fais cuire {x} au four à 200 °C pendant 15–20 min (ou à la poêle 4 min de chaque côté)',
    'Наріж {x} шматочками, обсмаж 5 хв і тушкуй під кришкою 40–45 хв, підливаючи воду': 'Coupe {x} en morceaux, fais revenir 5 min et mijote à couvert 40–45 min en ajoutant de l\'eau',
    'Наріж {x} і обсмаж на сковороді 15–20 хв до золотистої скоринки': 'Coupe {x} en tranches et fais dorer à la poêle 15–20 min',
    'Обсмаж {x} на сковороді 10–12 хв, розбиваючи грудочки': 'Fais revenir {x} à la poêle 10–12 min en écrasant les grumeaux',
    'Консервовану {x} промий і прогрій 3–5 хв (суху — замочи на ніч і вари 60–90 хв)': '{x} en conserve : rince et réchauffe 3–5 min (version sèche : trempe une nuit et cuis 60–90 min)',
    'Консервований {x} промий і прогрій 3–5 хв (сухий — замочи на ніч і вари 60–90 хв)': '{x} en conserve : rince et réchauffe 3–5 min (version sèche : trempe une nuit et cuis 60–90 min)',
    'Промий {x}, залий водою 1:2, доведи до кипіння й вари під кришкою на слабкому вогні 15–18 хв': 'Rince {x}, couvre d\'eau à raison de 1:2, porte à ébullition et cuis à couvert à feu doux 15–18 min',
    'Промий {x}, залий водою 1:2 і вари під кришкою на слабкому вогні 15–20 хв': 'Rince {x}, couvre d\'eau à raison de 1:2 et cuis à couvert à feu doux 15–20 min',
    'Вари {x} в киплячій підсоленій воді 8–10 хв (як на пачці) і злий воду': 'Fais cuire {x} dans l\'eau bouillante salée 8–10 min (comme sur le paquet) et égoutte',
    'Почисть {x}, наріж частками й запечи при 200 °C 30–35 хв (або звари в підсоленій воді 20 хв)': 'Épluche {x}, coupe en quartiers et fais cuire au four à 200 °C 30–35 min (ou à l\'eau salée 20 min)',
    'Залий {x} водою 1:2 і вари під кришкою 12–15 хв': 'Couvre {x} d\'eau à raison de 1:2 et cuis à couvert 12–15 min',
    'Залий {x} окропом 1:1, накрий на 5 хв і розпуши виделкою': 'Verse de l\'eau bouillante sur {x} à raison de 1:1, couvre 5 min et égrène à la fourchette',
    'Промий {x}, залий водою 1:3 і вари 25–40 хв до м\'якості': 'Rince {x}, couvre d\'eau à raison de 1:3 et cuis 25–40 min jusqu\'à ce que ce soit tendre',
    'Наріж {x} скибками; можна підсушити в тостері 2–3 хв': 'Coupe {x} en tranches ; tu peux faire griller au grille-pain 2–3 min',
    'Тонко нашаткуй {x} і пом\'ни руками з дрібкою солі — стане соковитішою': 'Émince finement {x} et malaxe à la main avec une pincée de sel — le résultat sera plus juteux',
    'Натри {x} на тертці': 'Râpe {x}',
    'Розбери {x} на суцвіття й звари на парі 5–7 хв (або 4 хв у киплячій воді)': 'Sépare {x} en bouquets et cuis à la vapeur 5–7 min (ou 4 min dans l\'eau bouillante)',
