    'Приклад профілю атлета: пауерліфтинг-аматор, станова — моя любов.': "Exemple de profil d'athlète : powerlifter amateur, le soulevé de terre, c'est mon truc.",
    'Приклад профілю атлета: пів року в залі, ціль — присід 70 кг.': "Exemple de profil d'athlète : six mois en salle, objectif — squat à 70 kg.",
    'Приклад профілю тренерки: жіночі групи, техніка з нуля, без страху перед залізом 🙌': 'Exemple de profil de coach : groupes de femmes, technique depuis zéro, sans peur de la fonte 🙌',
