    'Приклади профілів': 'Exemples de profils',
    'Присід: стопи на ширині плечей, коліна йдуть за носками, спина нейтральна. Глибина — до паралелі або нижче, якщо дозволяє мобільність.': "Squat : pieds à largeur d'épaules, genoux dans l'axe des orteils, dos neutre. Profondeur — jusqu'à la parallèle ou plus bas si la mobilité le permet.",
    'Присідання із вагою': 'Squats lestés',
    'Публікувати свої фото можна буде після входу — сервер спільноти ще підключається. Поки тут дописи Gym Log і приклади профілів.': "Tu pourras publier tes photos après la connexion — le serveur de la communauté est encore en cours de branchement. Pour l'instant, retrouve ici les publications de Gym Log et des exemples de profils.",
