    'Окрема програма на одну річ: качаєш її до цілі за рівнями й днями. Ваги тут немає — росте кількість повторень.': 'Un programma a parte per una cosa sola: la alleni fino all\'obiettivo per livelli e giorni. Qui non c\'è peso — crescono le ripetizioni.',
